"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["42173"],{70342(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.fase_cronograma.janela_obrigatoria_em_data_no_edital","status":422,"titulo":"Fase com data fixada no edital exige in\xedcio e t\xe9rmino do per\xedodo"},"descricao":{"codigo":"uniplus.selecao.fase_cronograma.janela_obrigatoria_em_data_no_edital","requisitos":[],"oQueAconteceu":["Cada fase can\xf4nica do cadastro diz quando a data da fase \xe9 fixada: no edital ou\\nna execu\xe7\xe3o. A fase cuja data \xe9 fixada no edital precisa trazer, no cronograma, o\\n`inicio` e o `fim` do per\xedodo; a fase cuja data \xe9 definida na execu\xe7\xe3o pode ficar\\nsem data, e a unidade respons\xe1vel a define depois. O pedido de defini\xe7\xe3o do\\ncronograma (`PUT .../cronograma-fases`) declarou uma fase de data no edital sem\\n`inicio`, sem `fim` ou sem os dois. A mensagem traz o c\xf3digo da fase, e a recusa\\nvem em `fases[n]`.","A origem da data n\xe3o \xe9 escolhida no pedido: vem da fase can\xf4nica citada em\\n`faseCanonicaId`. A confer\xeancia \xe9 feita ao montar cada fase, junto com as outras\\nviola\xe7\xf5es da mesma fase, e s\xf3 para a fase cujos atos foram montados sem recusa;\\numa viola\xe7\xe3o nos atos da fase pode esconder, at\xe9 ser corrigida, o per\xedodo\\nincompleto."],"comoResolver":["Informe `inicio` e `fim` da fase e repita a defini\xe7\xe3o do cronograma. Se a data da\\nfase n\xe3o deveria ser fixada no edital, a origem da data \xe9 uma propriedade da fase\\ncan\xf4nica no cadastro do m\xf3dulo Configura\xe7\xe3o, e a mudan\xe7a \xe9 de quem o gere; n\xe3o se\\ncorrige no cronograma do processo."],"ondeAparece":["Defini\xe7\xe3o do cronograma de fases do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Fase cronograma"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);